def req(identifier, name, description, inputs, outputs, pre, post, source, old, feature="Deferred", points=5, importance=60, demo=""):
    """Purpose: build a requirement dictionary. Inputs: requirement fields and trace links. Returns: a structured record."""
    return dict(id=identifier, name=name, description=description, inputs=inputs, outputs=outputs,
                precondition=pre, postcondition=post, source=source, old=old, feature=feature,
                estimate=points, importance=importance, demo=demo)


